221	function pickAnchorSentences(
222	  text: string,
223	  personaIds: string[],
224	): Record<string, string> {
225	  const sentences: string[] = [];
226	  for (const paragraph of text.split(/\n+/)) {
227	    const matches = paragraph.match(/[^.!?]+[.!?]+(?=\s|$)/g) ?? [];
228	    for (const raw of matches) {
229	      const sentence = raw.trim();
230	      if (sentence.split(/\s+/).length >= 6) sentences.push(sentence);
231	    }
232	  }
233	  if (sentences.length === 0) return {};
234	
235	  const used = new Set<number>();
236	  const take = (start: number): string | undefined => {
237	    for (let step = 0; step < sentences.length; step++) {
238	      const i = (start + step) % sentences.length;
239	      if (!used.has(i)) {
240	        used.add(i);
241	        return sentences[i];
242	      }
243	    }
244	    return undefined;
245	  };
246	
247	  const longest = sentences.reduce(
248	    (best, s, i) => (s.length > sentences[best].length ? i : best),
249	    0,
250	  );
251	  const evidence = sentences.findIndex((s) =>
252	    /\d|percent|study|studies|research|according to|evidence/i.test(s),
253	  );
254	  const claim = sentences.findIndex((s) =>
255	    /\b(must|should|clearly|obviously|always|never|every|all of|no one|undeniabl)/i.test(
256	      s,
257	    ),
258	  );
259	
260	  const preferred: Record<string, number> = {
261	    reader: 0,
262	    editor: longest,
263	    devil: claim >= 0 ? claim : Math.floor(sentences.length / 2),
264	    scholar: evidence >= 0 ? evidence : Math.floor((sentences.length * 2) / 3),
265	    angel: Math.floor(sentences.length / 3),
266	  };
267	
268	  const result: Record<string, string> = {};
269	  for (const id of personaIds) {
270	    if (id in preferred) {
271	      const s = take(preferred[id]);
272	      if (s) result[id] = s;
273	    }
274	  }
275	  let cursor = 0;
276	  for (const id of personaIds) {
277	    if (result[id] !== undefined || id in preferred) continue;
278	    const s = take(cursor++ % sentences.length);
279	    if (s) result[id] = s;
280	  }
281	  return result;
282	}
