590	  const requestFeedback = $(async () => {
591	    store.isGenerating = true;
592	    store.conveneError = null;
593	    store.convenedBriefTitle = brief?.answers.workingTitle ?? null;
594	    try {
595	      const draftText = await readCurrentDraftText();
596	      const readiness = draftReadiness(draftText, MIN_EDITOR_WORDS);
597	      if (!readiness.ok) {
598	        store.conveneError = localDraftValidationError("convene-room");
599	        store.lastProvider = null;
600	        return;
601	      }
602	      const client =
603	        auth.value.provider === "convex" && auth.value.user
604	          ? clientSig.value
605	          : null;
606	      // What the writer has been doing since the room last read. Costs
607	      // nothing to fetch and lets the editors respond to a direction rather
608	      // than to a cold snapshot.
609	      const trajectory = await currentTrajectoryDigest();
610	      let responses: Array<{
611	        personaId: string;
612	        text: string;
613	        type: PersonaFeedback["type"];
614	        provider: string;
615	        anchor?: string;
616	      }> = [];
617	
618	      // ── Try client-side AI first (BYOK) ─────────────────────────
619	      const settings = store.aiSettings;
620	      const hasByok = hasConfiguredAiProvider(settings);
621	      if (hasByok && settings) {
622	        try {
623	          const clientResults = await Promise.all(
624	            store.personas.map(async (p) => {
625	              const req = {
