2718	function timeAgo(timestamp: number): string {
2719	  const seconds = Math.floor((Date.now() - timestamp) / 1000);
2720	  if (seconds < 60) return "just now";
2721	  const minutes = Math.floor(seconds / 60);
2722	  if (minutes < 60) return `${minutes}m`;
2723	  const hours = Math.floor(minutes / 60);
2724	  if (hours < 24) return `${hours}h`;
2725	  return `${Math.floor(hours / 24)}d`;
